with scored as (select *, row_number() over (order by amount desc, id) as seq_no, lead(amount, 2) over (order by amount, id) as next_amount, avg(amount) over w_part as amount_avg_6_prior, lag(amount, 2) over (partition by status, order_id order by amount, id) as prev_amount, count(amount) over (partition by method order by cast(paid_at as bigint) range between 2592000 preceding and current row) as amount_count_30d from payments window w_part as (partition by status order by paid_at, id rows between 6 preceding and 1 preceding)) select method, round(avg(next_amount), 2) as avg_next_amount, approx_percentile(prev_amount, array(0.25, 0.5, 0.75)) as prev_amount_quartiles, sum(case when method = 'cash' then prev_amount else 0 end) as cash_prev_amount, round(sum(prev_amount) / nullif(count(case when status = 'REFUNDED' then 1 end), 0), 2) as prev_amount_per_refunded, sum(amount_avg_6_prior) filter (where status = 'FAILED') as failed_total_amount_avg_6_prior, stddev_samp(amount) as amount_stddev, grouping(method) as grouping_level from scored group by rollup (method)
